		"title": "NAMUGA debuts Stella-2 solid-state lidar powered by Lumotive",
		"slug": "media-namuga-debuts-stella-2-solid-state-lidar-powered-by-lumotive",
		"status": "published",
		"excerpt": "Coverage from Engineering.com.",
		"body": "<p>Originally published by Engineering.com.</p>",
		"publishedAt": "2025-05-22 00:00:00Z",
