		"title": "The 2024 GSA Award Nominees Revealed",
		"slug": "media-the-2024-gsa-award-nominees-revealed",
		"status": "published",
		"excerpt": "Coverage from Global Semiconductor Alliance.",
		"body": "<p>Originally published by Global Semiconductor Alliance.</p>",
