		"title": "3D lidar sensor with true solid-state beam steering",
		"slug": "media-3d-lidar-sensor-with-true-solid-state-beam-steering",
		"status": "published",
		"excerpt": "Coverage from Electronics360.",
		"body": "<p>Originally published by Electronics360.</p>",
