		"title": "Production begins on first optical beamforming chip",
		"slug": "media-production-begins-on-first-optical-beamforming-chip",
		"status": "published",
		"excerpt": "Coverage from Electronics 360.",
		"body": "<p>Originally published by Electronics 360.</p>",
		"publishedAt": "2024-05-02 00:00:00Z",
