		"title": "Lumotive Taps EDOM to Accelerate Solid-State Lidar Adoption in Taiwan",
		"slug": "media-lumotive-taps-edom-to-accelerate-solid-state-lidar-adoption-in-taiwan",
		"status": "published",
		"excerpt": "Coverage from EE Times Asia.",
		"body": "<p>Originally published by EE Times Asia.</p>",
		"publishedAt": "2024-04-17 00:00:00Z",
